function serializeConfiguredError(v: Error, superJson: SuperJSON, depth = 0, seen = new Set<Error>()): any {
  const options = superJson.errorStack!;
  seen.add(v);
  const matches = options.classFilter.length === 0 || options.classFilter.includes(v.name);
  const result: any = { name: v.name, message: matches && options.sanitizeMessage ? sanitizeMessage(v.message) : v.message };
  for (const prop of superJson.allowedErrorProps) {
    if (prop !== 'stack' && prop !== 'stackFrames' && prop !== 'cause' && prop !== 'errors') result[prop] = (v as any)[prop];
  }
  if (matches && typeof v.stack === 'string') {
    if (options.mode === 'string' && superJson.allowedErrorProps.includes('stack')) result.stack = processStackString(v.stack, options);
    if (options.mode === 'frames' && superJson.allowedErrorProps.includes('stackFrames')) result.stackFrames = processStackFrames(v.stack, options);
  }
  if (typeof AggregateError !== 'undefined' && v instanceof AggregateError) result.errors = v.errors;
  const cause = (v as any).cause;
  const limit = options.includeCauses === 'direct' ? 1 : options.includeCauses === 'deep' ? options.maxCauseDepth : 0;
  if (depth < limit && cause instanceof Error && !seen.has(cause)) result.cause = serializeConfiguredError(cause, superJson, depth + 1, seen);
  return superJson.errorClassRegistry.getProcessor(v.name)?.(result) ?? result;
}

function restoreConfiguredError(v: any, superJson: SuperJSON): Error {
  const e = new Error(v.message);
  e.name = v.name;
  e.stack = typeof v.stack === 'string' ? v.stack : Array.isArray(v.stackFrames) ? v.stackFrames.map((frame: any) => frame.raw).join('\n') : undefined;
  if ('stackFrames' in v) (e as any).stackFrames = v.stackFrames;
  if ('cause' in v) (e as any).cause = v.cause instanceof Error ? v.cause : restoreConfiguredError(v.cause, superJson);
  if ('errors' in v) (e as any).errors = v.errors;
  for (const prop of superJson.allowedErrorProps) {
    if (prop !== 'stack' && prop !== 'stackFrames' && prop !== 'cause' && prop !== 'errors' && prop in v) (e as any)[prop] = v[prop];
  }
  return e;
}

